$data=json_decode((string)file_get_contents('php://input'),true);if(!is_array($data))qv_fail('Invalid JSON.');$jobId=(int)($data['job_id']??0);$platform=(string)($data['platform']??'');if($jobId<=0||!isset(wt_social_video_platforms()[$platform]))qv_fail('Invalid job or platform.');wt_job($pdo,$jobId);
$title=trim((string)($data['title']??''));$caption=trim((string)($data['post_caption']??''));$items=(array)($data['items']??[]);if($title===''||$caption===''||count($items)<2||count($items)>50)qv_fail('A title, caption and 2–50 slides are required.');$voiceEnabled=(string)($data['voiceover_enabled']??'0')==='1';if($voiceEnabled&&stripos($caption,'AI voice')===false)$caption.="\n\nVoice-over generated with AI.";$voice=(string)($data['voice_name']??'cedar');if(!isset(wt_social_video_voices()[$voice]))$voice='cedar';$accent=(string)($data['voice_accent']??'australian');if(!isset(wt_social_video_accents()[$accent]))$accent='australian';$data['voice_accent']=$accent;$data['tts_settings']=wt_social_tts_settings($voice,$accent);$music=basename((string)($data['music_file']??''));if($music!==''&&$music!=='__auto__'&&!in_array($music,wt_social_music_files(),true))qv_fail('Selected music file is unavailable.');
